1	//! Drives decode at GQA group 7 (56/8) — unsupported even if group 5 is added
2	//! for Qwen3-14B — and asserts the FlashInfer throw surfaces as the -1
3	//! sentinel plus a message. Before the guard this aborted the whole process.
4	
5	use std::ffi::CStr;
6	use std::ffi::c_void;
7	use std::ptr;
8	
9	use anyhow::Result;
10	use anyhow::ensure;
11	use pegainfer_kernels::ffi;
12	
13	unsafe extern "C" {
14	    fn cudaMalloc(dev_ptr: *mut *mut c_void, size: usize) -> i32;
15	    fn cudaFree(dev_ptr: *mut c_void) -> i32;
16	    fn cudaSetDevice(device: i32) -> i32;
17	}
18	
19	struct DeviceBuf {
20	    ptr: *mut c_void,
21	}
22	
23	impl DeviceBuf {
24	    fn alloc(bytes: usize) -> Result<Self> {
25	        let mut ptr = ptr::null_mut();
26	        let rc = unsafe { cudaMalloc(&raw mut ptr, bytes) };
27	        ensure!(rc == 0, "cudaMalloc failed: {rc}");
28	        Ok(Self { ptr })
29	    }
30	}
31	
32	impl Drop for DeviceBuf {
33	    fn drop(&mut self) {
34	        unsafe { cudaFree(self.ptr) };
35	    }
36	}
37	
38	#[test]
39	fn unsupported_gqa_group_returns_sentinel_with_message() -> Result<()> {
40	    if unsafe { cudaSetDevice(0) } != 0 {
41	        eprintln!("skipping: no CUDA device");
42	        return Ok(());
43	    }
44	    let num_qo_heads = 56i32;
45	    let num_kv_heads = 8i32;
46	    let head_dim = 128i32;
47	    let page_size = 16i32;
48	
49	    let q = DeviceBuf::alloc((num_qo_heads * head_dim) as usize * 2)?;
50	    let output = DeviceBuf::alloc((num_qo_heads * head_dim) as usize * 2)?;
51	    let kv = DeviceBuf::alloc((2 * page_size * num_kv_heads * head_dim) as usize * 2)?;
52	    // Shared backing for the six metadata arrays; the dispatch rejects the
53	    // group size before any kernel reads them.
54	    let meta = DeviceBuf::alloc(8 * std::mem::size_of::<i32>())?;
55	
56	    let result = unsafe {
57	        ffi::paged_attention_decode_cuda(
58	            q.ptr.cast(),
59	            output.ptr.cast(),
60	            kv.ptr.cast(),
61	            0,
62	            (page_size * num_kv_heads * head_dim) as i64,
63	            meta.ptr.cast(),
64	            meta.ptr.cast(),
65	            meta.ptr.cast(),
66	            meta.ptr.cast(),
67	            meta.ptr.cast(),
68	            meta.ptr.cast(),
69	            num_qo_heads,
70	            num_kv_heads,
71	            head_dim,
72	            page_size,
73	            1,
74	            (2 * page_size * num_kv_heads * head_dim) as i64,
75	            1.0,
76	            ptr::null_mut(),
77	        )
78	    };
79	    ensure!(result == -1, "expected the -1 sentinel, got {result}");
80	
81	    let msg = unsafe { CStr::from_ptr(ffi::pegainfer_kernels_last_error()) }.to_string_lossy();
82	    // The exact wording belongs to FlashInfer.
83	    ensure!(msg.contains("group_size"), "unexpected message: {msg}");
84	    Ok(())
85	}
